package com.smarthub.smartmaterial.badge;
import android.content.*;import android.graphics.drawable.GradientDrawable;import android.view.Gravity;import android.widget.TextView;import com.smarthub.smartmaterial.theme.*;
public class SmartBadge extends TextView{private int badgeColor,badgeTextColor;public SmartBadge(Context c){super(c);init();}public SmartBadge(Context c,android.util.AttributeSet a){super(c,a);init();}public SmartBadge(Context c,android.util.AttributeSet a,int s){super(c,a,s);init();}private int dp(float v){return SmartDimensions.dp(getContext(),v);}private void init(){badgeColor=SmartTheme.primary(getContext());badgeTextColor=SmartTheme.isDark(getContext())?SmartDarkColors.ON_PRIMARY:SmartColors.ON_PRIMARY;setGravity(Gravity.CENTER);setTextSize(12);setTextColor(badgeTextColor);setPadding(dp(8),dp(3),dp(8),dp(3));setMinHeight(dp(24));updateBackground();}private void updateBackground(){GradientDrawable d=new GradientDrawable();d.setColor(badgeColor);d.setCornerRadius(dp(12));setBackground(d);}public SmartBadge setBadgeText(CharSequence t){setText(t);setContentDescription(t);return this;}public SmartBadge setBadgeColor(int c){badgeColor=c;updateBackground();return this;}public SmartBadge setBadgeTextColor(int c){badgeTextColor=c;setTextColor(c);return this;}}
